function Trend({items}:{items:Row[]}){
 const values=items.slice().sort((a,b)=>new Date(a.measured_at).getTime()-new Date(b.measured_at).getTime()).slice(-14);if(values.length<2)return <Blank title="Il trend appare con almeno due rilevazioni">La singola misura resta disponibile nello storico.</Blank>;
 const low=Math.min(...values.flatMap(v=>v.second_value?[v.value,v.second_value]:[v.value])),high=Math.max(...values.flatMap(v=>v.second_value?[v.value,v.second_value]:[v.value]));const spread=high-low||10;const y=(v:number)=>142-((v-low)/spread)*102;const firstTime=new Date(values[0].measured_at).getTime(),lastTime=new Date(values[values.length-1].measured_at).getTime();const x=(i:number)=>42+530*(new Date(values[i].measured_at).getTime()-firstTime)/(lastTime-firstTime||1);const points=values.map((v,i)=>`${x(i)},${y(v.value)}`).join(' ');const secondary=values[0].second_value?values.map((v,i)=>`${x(i)},${y(v.second_value)}`).join(' '):'';
 return <figure className="care-chart"><svg viewBox="0 0 620 196" role="img" aria-label={`Andamento delle ultime ${values.length} misurazioni, da ${low} a ${high} ${values[0].unit}`}><line x1="42" y1="142" x2="580" y2="142" stroke="#d8e4e7"/><line x1="42" y1="40" x2="580" y2="40" stroke="#e6eff0"/><text x="4" y="46">{high}</text><text x="4" y="146">{low}</text><polyline points={points} fill="none" stroke="#147c80" strokeWidth="3" strokeLinejoin="round"/>{secondary&&<polyline points={secondary} fill="none" stroke="#8eaa63" strokeWidth="3"/>}{values.map((v,i)=><circle key={v.id} cx={x(i)} cy={y(v.value)} r="4" fill="#147c80"><title>{dt(v.measured_at)}: {v.value} {v.unit}</title></circle>)}<text x="42" y="180">{date(values[0].measured_at)}</text><text x="580" y="180" textAnchor="end">{date(values[values.length-1].measured_at)}</text></svg><figcaption>{values[0].unit} · {secondary?'linea verde: sistolica · linea oliva: diastolica':'andamento dei valori inseriti'}. Il grafico non attribuisce una diagnosi.</figcaption></figure>;
}
function MonitoringView({data,act}:ViewProps){
 const [metric,setMetric]=useState('pressione'),[show,setShow]=useState(false),[busy,setBusy]=useState(false),[reviewing,setReviewing]=useState(''),[review,setReview]=useState('');
 const [form,setForm]=useState({metric:'pressione',value:'',second_value:'',measured_at:localNow(),setting:'domicilio',context:'',flagged:false});const [range,setRange]=useState({metric:'pressione',min:'',max:'',note:''});
 const readings=data.readings.filter(v=>v.metric===metric).sort((a,b)=>new Date(b.measured_at).getTime()-new Date(a.measured_at).getTime());
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);try{await act('/workspace/readings',{...form,patient_id:data.patient!.id,measured_at:new Date(form.measured_at).toISOString()});setMetric(form.metric);setForm({...form,value:'',second_value:'',context:'',flagged:false});setShow(false);}catch{}finally{setBusy(false);}}
 async function saveRange(e:FormEvent){e.preventDefault();setBusy(true);try{await act('/workspace/ranges',{...range,patient_id:data.patient!.id});}catch{}finally{setBusy(false);}}
 return <><section className="care-subheading"><p>La persona inserisce valori, orario e contesto. Il team consulta l’andamento e annota la propria revisione.</p><button className="button" onClick={()=>setShow(v=>!v)}><Plus size={17}/> {show?'Chiudi':'Registra una misurazione'}</button></section>{show&&<form className="card care-form-grid care-section-gap" onSubmit={submit}><PanelTitle title="Nuova rilevazione"/><label className="field care-span-2">Parametro<select value={form.metric} onChange={e=>setForm({...form,metric:e.target.value,value:'',second_value:''})}>{Object.entries(metricNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label className="field">{form.metric==='pressione'?'Pressione sistolica (mmHg)':`${metricNames[form.metric]} (${({frequenza:'bpm',saturazione:'%',temperatura:'°C',peso:'kg',glicemia:'mg/dL'} as Record<string,string>)[form.metric]})`}<input type="number" step="any" required value={form.value} onChange={e=>setForm({...form,value:e.target.value})}/></label>{form.metric==='pressione'?<label className="field">Pressione diastolica (mmHg)<input type="number" step="any" required value={form.second_value} onChange={e=>setForm({...form,second_value:e.target.value})}/></label>:<div/>}<label className="field">Data e ora della misura<input type="datetime-local" required value={form.measured_at} onChange={e=>setForm({...form,measured_at:e.target.value})}/></label><label className="field">Contesto<select value={form.setting} onChange={e=>setForm({...form,setting:e.target.value})}><option value="domicilio">A domicilio</option><option value="ambulatorio">In ambulatorio</option></select></label><label className="field care-span-2">Note e condizioni della misura<textarea value={form.context} onChange={e=>setForm({...form,context:e.target.value})} placeholder="Come è stata rilevata? Ci sono osservazioni da condividere?"/></label><label className="checkbox-line care-span-2"><input type="checkbox" checked={form.flagged} onChange={e=>setForm({...form,flagged:e.target.checked})}/><span>Desidero segnalare questa misura al team come criticità da valutare.</span></label><div className="care-span-2"><button className="button" disabled={busy}>Salva la rilevazione</button></div></form>}
 <div className="care-monitor-cards">{Object.entries(metricNames).map(([key,name])=>{const last=data.readings.filter(r=>r.metric===key).sort((a,b)=>new Date(b.measured_at).getTime()-new Date(a.measured_at).getTime())[0];return <button key={key} className={`care-monitor-card ${metric===key?'selected':''}`} onClick={()=>setMetric(key)} aria-pressed={metric===key}><span>{name}</span><strong>{last?`${last.value}${last.second_value?'/'+last.second_value:''}`:'—'}<small>{last?.unit||''}</small></strong><small>{last?date(last.measured_at):'Nessuna misura'}</small></button>;})}</div><section className="card"><PanelTitle title={`Andamento · ${metricNames[metric]}`} action={<span className="care-tag">{readings.length} rilevazioni</span>}/><Trend items={readings}/>{data.ranges.filter(r=>r.metric===metric).map(r=><div className="care-range-note" key={r.metric}>Limiti impostati nel percorso: {r.min??'nessun minimo'} / {r.max??'nessun massimo'} · {r.author_name}. {r.note}</div>)}{!data.ranges.some(r=>r.metric===metric)&&<p className="care-meta">Nessuna soglia clinica impostata. I valori sono visualizzati senza interpretazione automatica.</p>}</section><section className="card care-section-gap"><PanelTitle title="Diario delle rilevazioni"/><div className="care-reading-list">{readings.map(r=><article key={r.id}><div className="row between"><strong>{r.value}{r.second_value?'/'+r.second_value:''} {r.unit}</strong>{status(r.status)}</div><p>{dt(r.measured_at)} · {r.setting==='domicilio'?'domicilio':'ambulatorio'} · {r.author_name}</p>{r.context&&<p className="care-preserve-text">{r.context}</p>}{r.flagged&&<span className="care-tag tag-to_review">Segnalato al team · {r.range_reason||'richiesta di valutazione'}</span>}{r.reviews.map((review:Row,i:number)=><div className="care-review" key={i}><strong>{review.author_name}</strong><p>{review.body}</p><small>{dt(review.at)}</small></div>)}{data.capabilities.operator&&<button className="button ghost small" onClick={()=>setReviewing(reviewing===r.id?'':r.id)}>Annota la revisione</button>}{reviewing===r.id&&<div className="care-inline-form"><label className="field">Commento del team<textarea value={review} onChange={e=>setReview(e.target.value)}/></label><button className="button small" disabled={!review.trim()} onClick={()=>void act(`/workspace/readings/${r.id}/review`,{patient_id:data.patient!.id,note:review}).then(()=>{setReviewing('');setReview('');}).catch(()=>{})}>Registra revisione</button></div>}</article>)}</div>{!readings.length&&<Blank title="Nessuna misura per questo parametro"/>}</section>{data.capabilities.clinician&&<details className="card care-section-gap"><summary className="care-details-title">Imposta i limiti concordati del monitoraggio</summary><p>Configurazione del medico per il singolo percorso. I valori fuori limite entrano tra le criticità da valutare; non generano una diagnosi né un invio automatico di soccorso.</p><form className="care-form-grid" onSubmit={saveRange}><label className="field care-span-2">Parametro<select value={range.metric} onChange={e=>setRange({...range,metric:e.target.value})}>{Object.entries(metricNames).map(([v,l])=><option key={v} value={v}>{l}{v==='pressione'?' · sistolica':''}</option>)}</select></label><label className="field">Limite inferiore · facoltativo<input type="number" step="any" value={range.min} onChange={e=>setRange({...range,min:e.target.value})}/></label><label className="field">Limite superiore · facoltativo<input type="number" step="any" value={range.max} onChange={e=>setRange({...range,max:e.target.value})}/></label><label className="field care-span-2">Indicazioni sul contesto<textarea value={range.note} onChange={e=>setRange({...range,note:e.target.value})}/></label><div className="care-span-2"><button className="button secondary" disabled={busy}>Salva i limiti nella prova</button></div></form></details>}<p className="care-service-note">Il monitoraggio dimostra l’interazione manuale paziente–app. Per un’emergenza chiama il 112.</p></>;
}

function MessagesView({data,user,act}:ViewProps){
 const [channel,setChannel]=useState('patient_team'),[body,setBody]=useState(''),[busy,setBusy]=useState(false);const messages=data.messages.filter(m=>m.channel===channel);
 async function send(e:FormEvent){e.preventDefault();setBusy(true);try{await act('/workspace/messages',{patient_id:data.patient!.id,body,channel});setBody('');}catch{}finally{setBusy(false);}}
 return <><div className="care-message-header"><div><span className="care-team-avatar"><Users size={20}/></span><div><strong>Team di cura di {data.patient!.first_name}</strong><p>{data.team.filter(t=>t.active).map(t=>t.profession).join(' · ')}</p></div></div><Link href="/team" className="care-text-link">Vedi il team <ArrowRight size={14}/></Link></div>{data.capabilities.internal&&<div className="care-filter-row"><button className={`care-filter ${channel==='patient_team'?'active':''}`} onClick={()=>setChannel('patient_team')}>Dialogo con paziente e caregiver</button><button className={`care-filter ${channel==='team'?'active':''}`} onClick={()=>setChannel('team')}>Coordinamento tra professionisti</button></div>}<section className="card care-conversation"><div className="care-message-history">{messages.map(m=><article key={m.id} className={`care-message ${m.author_id===user.id?'own':''}`}><strong>{m.author_name}</strong><p className="care-preserve-text">{m.body}</p><div className="row between"><small>{dt(m.created_at)}</small><span className="care-meta">{m.read_by.length?'Presa visione registrata':'Salvato nella demo'}</span></div>{m.author_id!==user.id&&!m.read_by.includes(user.id)&&<button className="care-text-button" onClick={()=>void act(`/workspace/messages/${m.id}/read`,{patient_id:data.patient!.id}).catch(()=>{})}><Check size={13}/>Conferma presa visione</button>}</article>)}{!messages.length&&<Blank title={channel==='team'?'Inizia il coordinamento professionale':'Inizia un dialogo con il team'}/>}</div><form className="care-message-compose" onSubmit={send}><label className="field">{channel==='team'?'Messaggio riservato ai professionisti assegnati':'Messaggio al team di cura'}<textarea required rows={3} maxLength={3000} value={body} onChange={e=>setBody(e.target.value)} placeholder="Scrivi una domanda o condividi un’osservazione…"/></label><div className="row between"><small>Le comunicazioni restano associate a questo percorso.</small><button className="button" disabled={busy||!body.trim()}>{busy?'Salvataggio…':'Invia messaggio'}</button></div></form></section><p className="care-service-note">Nella demo il messaggio viene salvato nello stesso browser e può essere visto cambiando profilo. Nel servizio reale saranno definiti tempi di lettura e risposta. Per un’emergenza chiama il 112.</p></>;
}
function EducationView({data,act}:ViewProps){
 const [condition,setCondition]=useState('all'),[show,setShow]=useState(false),[busy,setBusy]=useState(false),[form,setForm]=useState({title:'',condition:'',body:'',family_visible:true});
 const conditions=Array.from(new Set(data.education.map(v=>v.condition)));
 async function create(e:FormEvent){e.preventDefault();setBusy(true);try{await act('/workspace/education',{...form,patient_id:data.patient!.id});setShow(false);setForm({title:'',condition:'',body:'',family_visible:true});}catch{}finally{setBusy(false);}}
 return <><section className="care-subheading"><p>Indicazioni collegate al percorso, con autore, versione e data. Gli approfondimenti accompagnano il dialogo con il team.</p>{data.capabilities.clinician&&<button className="button" onClick={()=>setShow(v=>!v)}><Plus size={17}/>Prepara indicazioni</button>}</section><section className="card care-soft-card"><PanelTitle title="Il trattamento concordato"/>{data.therapies.length?data.therapies.map(t=><div key={t.id} className="care-treatment"><strong>{t.medication_name}</strong><p>{t.instructions||'Segui le istruzioni condivise dal professionista.'}</p><small>{t.dosage} · piano dimostrativo</small></div>):<p>Non è stato inserito un piano terapeutico in questo percorso di prova. Il medico condivide qui le indicazioni concordate; l’app non propone autonomamente farmaci o dosaggi.</p>}</section>{show&&<form className="card care-form-grid care-section-gap" onSubmit={create}><PanelTitle title="Nuove indicazioni del medico"/><label className="field">Titolo<input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label className="field">Patologia o obiettivo del percorso<input value={form.condition} onChange={e=>setForm({...form,condition:e.target.value})}/></label><label className="field care-span-2">Indicazioni concordate<textarea required rows={5} value={form.body} onChange={e=>setForm({...form,body:e.target.value})}/></label><label className="checkbox-line care-span-2"><input type="checkbox" checked={form.family_visible} onChange={e=>setForm({...form,family_visible:e.target.checked})}/><span>Condividi anche con il caregiver delegato.</span></label><div className="care-span-2"><button className="button" disabled={busy}>Salva in bozza</button></div></form>}
 <div className="care-filter-row"><button className={`care-filter ${condition==='all'?'active':''}`} onClick={()=>setCondition('all')}>Tutte le indicazioni</button>{conditions.map(c=><button key={c} className={`care-filter ${condition===c?'active':''}`} onClick={()=>setCondition(c)}>{c}</button>)}</div><div className="care-education-grid">{data.education.filter(v=>condition==='all'||v.condition===condition).map(resource=>{const read=data.progress.some(p=>p.resource_id===resource.id);return <article className="card care-education-card" key={resource.id}><div className="row between"><span className="eyebrow">{resource.condition}</span>{status(resource.status)}</div><h2>{resource.title}</h2><p className="care-preserve-text">{resource.body}</p><div className="care-education-source"><strong>{resource.author_name}</strong><span>Versione {resource.version} · {date(resource.updated_at)}</span>{resource.source_url?<a href={resource.source_url} target="_blank" rel="noopener noreferrer">Approfondimento: {resource.source_title} <ArrowRight size={13}/></a>:<span>{resource.source_title}</span>}</div><div className="row care-section-gap">{resource.status==='published'?<button className="button secondary small" disabled={read} onClick={()=>void act(`/workspace/education/${resource.id}/progress`,{patient_id:data.patient!.id}).catch(()=>{})}>{read?<><CheckCircle2 size={16}/>Preso in visione</>:'Segna come letto'}</button>:data.capabilities.clinician&&<button className="button small" onClick={()=>void act(`/workspace/education/${resource.id}/publish`,{patient_id:data.patient!.id}).catch(()=>{})}>Pubblica per il paziente</button>}</div></article>;})}</div>{!data.education.length&&<Blank title="Nessuna indicazione pubblicata per questo percorso">Le indicazioni specifiche vengono predisposte dal professionista.</Blank>}</>;
}
function TeamView({data,act}:ViewProps){
 const [busy,setBusy]=useState(''),[expires,setExpires]=useState<Record<string,string>>({});
 async function save(member:Row,active:boolean){setBusy(member.id);try{await act(`/workspace/team/${member.id}`,{patient_id:data.patient!.id,active,expires_at:Object.prototype.hasOwnProperty.call(expires,member.id)?(expires[member.id]?new Date(`${expires[member.id]}T23:59:00`).toISOString():null):member.expires_at||null});}catch{}finally{setBusy('');}}
 const levels=[['0','Paziente','Consulta il proprio percorso, riferisce osservazioni, inserisce misure e documenti. La revisione clinica resta del professionista.'],['1','Caregiver delegato','Supporta il percorso assegnato e vede soltanto i documenti condivisi con la famiglia. Nessun potere di consenso sanitario nella demo.'],['2','Operatore assegnato','Aggiunge osservazioni e misure, consulta i documenti del team e partecipa al coordinamento professionale.'],['3','Medico assegnato','Aggiunge valutazioni, revisiona gli esami, prepara e verifica i consensi, pubblica le indicazioni di autocura.'],['4','Medico referente','Coordina il percorso e gestisce le assegnazioni professionali, oltre alle proprie funzioni cliniche.']];
 return <><section className="card care-soft-card"><PanelTitle title="Un ruolo non apre tutte le cartelle">L’accesso richiede un’assegnazione attiva al paziente. Per gli esami conta anche la condivisione del singolo documento.</PanelTitle><p>La segreteria gestisce gli appuntamenti; l’amministrazione gestisce le operazioni organizzative. Nessuno dei due profili accede automaticamente alla cartella clinica.</p></section><div className="care-team-grid care-section-gap">{data.team.map(member=><article className="card care-team-card" key={member.id}><span className="care-team-avatar">{member.role==='medico'?<Stethoscope size={22}/>:<Users size={22}/>}</span><h3>{member.name}</h3><p>{member.profession}</p><span className={`care-tag ${member.active?'tag-reviewed':''}`}>{member.active?'Assegnazione attiva':'Assegnazione sospesa'}</span>{member.expires_at&&<small>Scadenza: {date(member.expires_at)}</small>}{member.coordinator&&<span className="care-meta">Coordina questo percorso</span>}{data.capabilities.coordinator&&!member.coordinator&&<div className="care-inline-form"><label className="field">Scadenza dell’incarico<input type="date" value={expires[member.id]??member.expires_at?.slice(0,10)??''} onChange={e=>setExpires({...expires,[member.id]:e.target.value})}/></label><div className="row"><button className="button secondary small" disabled={busy===member.id} onClick={()=>void save(member,true)}>Conferma assegnazione</button><button className="button ghost small" disabled={busy===member.id||!member.active} onClick={()=>void save(member,false)}>Sospendi accesso</button></div></div>}</article>)}</div><section className="card care-section-gap"><PanelTitle title="Gradi di autorizzazione del percorso">Le capacità aumentano per funzione; non attribuiscono un accesso indiscriminato ai dati.</PanelTitle><div className="care-permission-table table-wrap"><table><thead><tr><th>Grado</th><th>Profilo</th><th>Funzioni nel percorso</th></tr></thead><tbody>{levels.map(([n,role,desc])=><tr key={n}><td><span className="care-permission-level">{n}</span></td><td><strong>{role}</strong></td><td>{desc}</td></tr>)}</tbody></table></div><p className="care-meta">Il referente è il medico del percorso, non l’amministratore tecnico. Le autorizzazioni mostrate sono un modello dimostrativo: nel servizio reale vengono applicate sul server.</p></section></>;
}
